from lib import *
r=[]
r.append(R(6520840,"पालक, एवोकाडो और गर्मियों की बेरी का सलाद",
"यह सुपरफूड सलाद एंटीऑक्सीडेंट से भरपूर है और इसमें गर्मियों के ताज़ा स्वाद हैं। इसे ग्रिल्ड चिकन के किसी व्यंजन, जैसे ग्रिल्ड लाइम चिकन फ़ाजिटा, या मछली के व्यंजन, जैसे आम और टमाटर की सालसा के साथ ग्रिल्ड सैल्मन, के साथ परोसें। सलाद ड्रेसिंग बनाने का आसान तरीका चाहिए? ड्रेसिंग की सारी सामग्री ढक्कन वाले जार में डालें। ढक्कन को कसकर बंद करें और सब कुछ अच्छी तरह मिलने तक ज़ोर से हिलाएँ। अगर आप यह सलाद पहले से बना रहे हैं, तो ड्रेसिंग परोसने से ठीक पहले ही डालें।",
"8","1 कप",
["10 औंस ताज़ा बेबी पालक","1 कप कटी हुई या स्लाइस की हुई स्ट्रॉबेरी","1/2 कप ब्लूबेरी","1 मध्यम एवोकाडो (टुकड़ों में कटा हुआ)","1/3 कप बारीक कटा हुआ या स्लाइस किया हुआ लाल प्याज़","2 बड़े चम्मच जैतून का तेल","2 बड़े चम्मच सफ़ेद बाल्सैमिक या शैम्पेन सिरका","1 छोटा चम्मच शहद","1 बड़ा चम्मच नीबू (रस निकाला हुआ)","1 कली लहसुन (बारीक कटी हुई)","1/4 छोटा चम्मच काली मिर्च"],
["पालक, स्ट्रॉबेरी, ब्लूबेरी, एवोकाडो और प्याज़ को एक बड़े सलाद कटोरे में रखें।","एक छोटे कटोरे में जैतून का तेल, सिरका, शहद, नीबू का रस, लहसुन और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद पर डालें और अच्छी तरह मिलाएँ ताकि सब पर बराबर लग जाए।"]))
r.append(R(6520930,"टर्की और पालक भरे मशरूम",
"हमारे टर्की और पालक भरे मशरूम के साथ अपने स्टार्टर को एक नए स्तर पर ले जाएँ। यह स्वादिष्ट व्यंजन आम क्रेमिनी मशरूम को एक-एक निवाले के लज़ीज़ टुकड़ों में बदल देता है। इन छोटे-छोटे पावरहाउस में क्रेमिनी मशरूम के भीतर ताज़े पालक, कम चर्बी वाली कीमा टर्की और थोड़े से पारमेज़न का जानदार मिश्रण भरा जाता है, जो एक क्लासिक व्यंजन को मधुमेह के अनुकूल रूप देता है।",
"8","2 भरे हुए मशरूम",
["2 स्प्रे, 0.5 ग्राम नॉनस्टिक कुकिंग स्प्रे","1/2 पाउंड कम चर्बी वाली कीमा टर्की","1/4 कप प्याज़ (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 कप बेबी पालक (कटा हुआ)","16 बड़े क्रेमिनी (बेबी बेला) मशरूम (साफ़ किए हुए और डंठल निकाले हुए)","1/4 कप पारमेज़न चीज़ (कसा हुआ)","1/2 छोटा चम्मच सूखा ओरेगानो","1/2 छोटा चम्मच सूखा रोज़मेरी","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["अपने ओवन को 375 डिग्री F पर पहले से गरम करें और बेकिंग शीट पर बेकिंग पेपर बिछाकर या उस पर कुकिंग स्प्रे से हल्की चिकनाई लगाकर तैयार करें।","एक कड़ाही में मध्यम आँच पर कम चर्बी वाली कीमा टर्की को छोटे टुकड़ों में तोड़ते हुए तब तक पकाएँ जब तक वह भूरी होकर पूरी तरह पक न जाए। अतिरिक्त चर्बी निकाल दें।","उसी कड़ाही में बारीक कटा प्याज़ और कटा हुआ लहसुन डालें और 2–3 मिनट तक भूनें, जब तक उनकी खुशबू न आने लगे और वे हल्के नरम न हो जाएँ।","कड़ाही में कटा हुआ ताज़ा पालक डालें और 2–3 मिनट और पकाएँ, जब तक वह गल न जाए और अतिरिक्त नमी सूख न जाए।","कसा हुआ पारमेज़न चीज़, सूखा ओरेगानो और रोज़मेरी मिलाएँ। मिश्रण में नमक और काली मिर्च डालें। अच्छी तरह मिलाएँ और थोड़ा ठंडा होने दें।","साफ़ किए हुए मशरूम लें और उन पर कुकिंग स्प्रे या जैतून के तेल से हल्का ब्रश करें या स्प्रे करें। उन्हें तैयार की गई बेकिंग शीट पर गिल वाला हिस्सा ऊपर की ओर रखकर सजाएँ।","हर मशरूम कैप में टर्की और पालक का मिश्रण भरें और उसे हल्का दबाकर कस दें।","भरे हुए मशरूम को पहले से गरम ओवन में लगभग 15–20 मिनट तक या तब तक बेक करें जब तक मशरूम नरम न हो जाएँ और भरावन अंदर तक गरम होकर हल्का भूरा न हो जाए।","भरे हुए मशरूम को ओवन से निकालें और परोसने से पहले कुछ मिनट ठंडा होने दें।"]))
r.append(R(6521634,"दालचीनी वाले भुने हुए नाशपाती",
"फल भोजन का एक बढ़िया समापन होता है। फलों को भूनने और ग्रिल करने के प्रयोग से आप उनका अधिकतम स्वाद निखार सकते हैं। यह रेसिपी सेब से भी आसानी से बनाई जा सकती है।",
"4","1/2 नाशपाती",
["1 बड़ा चम्मच स्मार्ट बैलेंस मार्जरीन","1/2 छोटा चम्मच पिसी दालचीनी","2 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","2 मध्यम आंजू नाशपाती (लगभग 6.5 औंस प्रत्येक, छिली हुई, बीज निकाले हुए और आधी कटी हुई)","1 बड़ा चम्मच अखरोट (कटे हुए)","1/4 कप पानी"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक छोटे कटोरे में (उँगलियों से) मार्जरीन, दालचीनी और ब्राउन शुगर को मिलाएँ। अखरोट डालकर मिलाएँ।","नाशपाती के आधे हिस्सों को कटी हुई सतह ऊपर की ओर रखकर 8 इंच के चौकोर काँच के बेकिंग डिश में सजाएँ। डिश की तली में 1/4 कप पानी डालें।","ब्राउन शुगर के मिश्रण को नाशपाती के सभी आधे हिस्सों में बराबर बाँटें और नाशपाती के बीच में रखें।","नाशपाती के नरम होने और भूरा होना शुरू होने तक लगभग 45 मिनट बेक करें।"]))
r.append(R(6523355,"शाकाहारी बेक्ड बीन्स",
"अगर आपको नेवी बीन्स से ज़्यादा पिंटो बीन्स पसंद हैं, तो आप ये बेक्ड बीन्स पिंटो बीन्स से भी बना सकते हैं।",
"6","1/3 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा प्याज़ (टुकड़ों में कटा हुआ)","2 (14.5 औंस के) डिब्बे नेवी या ग्रेट नॉर्दर्न बीन्स (धुले और पानी निथारे हुए)","1 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1/4 कप बिना नमक मिलाया केचप","1/4 कप कम कैलोरी वाला ब्राउन शुगर विकल्प","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच डिजॉन मस्टर्ड","1 छोटा चम्मच लहसुन पाउडर"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। 8 इंच के बेकिंग पैन में कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","सारी सामग्री को एक बड़े कटोरे में मिलाएँ। तैयार बेकिंग पैन में डालें। ढककर 45 मिनट बेक करें। फिर ढक्कन हटाकर और 30 से 40 मिनट या गाढ़ा होने तक बेक करें।"]))
r.append(R(6523505,"खीरा और मूली का सलाद",
"क्या आपको ताज़ी सब्ज़ियों का स्वाद पसंद है? तो इस खीरे और मूली के सलाद को ज़रूर चखें! ताज़ी जड़ी-बूटियों और आसान सलाद ड्रेसिंग के साथ यह किसी भी भोजन में थोड़ा और रंग जोड़ने के लिए एक बढ़िया स्टार्टर या साइड सलाद है।",
"6","1 कप",
["2 मध्यम खीरे (पतले स्लाइस में कटे हुए)","1 कप मूली (पतले स्लाइस में कटी हुई)","1/4 कप लाल प्याज़ (पतले स्लाइस में कटा हुआ)","2 बड़े चम्मच ताज़ा सोआ (कटा हुआ)","2 बड़े चम्मच ताज़ा अजमोद (कटा हुआ)","2 बड़े चम्मच सफ़ेद वाइन सिरका","2 बड़े चम्मच जैतून का तेल","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक बड़े कटोरे में पतले कटे खीरे, मूली, लाल प्याज़, कटा हुआ ताज़ा सोआ और ताज़ा अजमोद मिलाएँ।","एक छोटे कटोरे में सफ़ेद वाइन सिरका, जैतून का तेल, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को खीरे, मूली और जड़ी-बूटियों के मिश्रण पर डालें।","सलाद को धीरे से मिलाएँ ताकि ड्रेसिंग सब पर बराबर लग जाए।","स्वाद निखारने के लिए सलाद को रेफ़्रिजरेटर में कम से कम 15 मिनट मैरिनेट होने दें।"]))
r.append(R(6523847,"किफ़ायती ग्रीक सलाद और ग्रिल्ड झींगा पिटा",
"इस व्यंजन को एक कप ठंडे गज़पाचो सूप के साथ या नीबू के रस और ओरेगानो के साथ भुनी हुई तोरी के साथ परोसें।",
"4","1/2 पिटा + 4 झींगे + 3/4 कप सलाद",
["2 कप रोमेन लेट्यूस (बारीक कटा हुआ)","1/2 छोटा लाल प्याज़ (पतले स्लाइस में कटा हुआ)","1/2 बड़ा या 1 छोटा खीरा (छिला और स्लाइस किया हुआ)","1/3 कप फ़ेटा चीज़ (कम चर्बी वाला, चूरा किया हुआ)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच रेड वाइन सिरका","1 बड़ा चम्मच ताज़ा ओरेगानो (कटा हुआ)","2 मध्यम साबुत गेहूँ के पिटा (आधे कटे हुए)","12 मध्यम झींगे (छिले और नस निकाले हुए)","1 छोटा चम्मच नमक (वैकल्पिक)","1 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच लाल मिर्च (केयेन)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["इनडोर या आउटडोर ग्रिल तैयार करें।","एक बड़े कटोरे में लेट्यूस, प्याज़, खीरा, फ़ेटा चीज़, जैतून का तेल, रेड वाइन सिरका और ओरेगानो को मिलाएँ।","पिटा के हर आधे पॉकेट में लेट्यूस के मिश्रण का 1/4 भाग भरें। एक तरफ़ रख दें।","झींगों पर नमक (वैकल्पिक), पिसी काली मिर्च और लाल मिर्च (केयेन) छिड़कें। झींगों पर कुकिंग स्प्रे करें।","झींगों को हर तरफ़ 3-4 मिनट ग्रिल करें। ग्रिल से निकालें और हर पिटा में 3 झींगे डालें।"]))
r.append(R(6523980,"गार्डन हार्वेस्ट सूप",
"इस सूप में सब्ज़ियाँ अपने रेफ़्रिजरेटर में मौजूद सब्ज़ियों के अनुसार बदल लें। सब्ज़ियों के मिश्रण के साथ रचनात्मक बनें!",
"2","1 ¼ कप",
["1 छोटा चम्मच जैतून का तेल","2 कप सब्ज़ियाँ (कच्ची, कटी हुई, जैसे शिमला मिर्च, गाजर, हरी बीन्स, पीला समर स्क्वैश या तोरी का कोई भी मिश्रण)","1/4 कप प्याज़ (बारीक कटा हुआ)","1 छोटा चम्मच इटैलियन सीज़निंग मिश्रण (हाथ से मसला हुआ)","2 कप कम सोडियम वाला चिकन ब्रॉथ (कम सोडियम वाला वेजिटेबल ब्रॉथ या फ़ैट-फ़्री, कम सोडियम वाला)","1 कप ताज़ी पालक की पत्तियाँ (हल्के से भरी हुई, मोटी कटी हुई)","1 बड़ा चम्मच पारमेज़न चीज़ (कद्दूकस की हुई या बारीक कसी हुई)"],
["एक मध्यम सॉसपैन में मध्यम आँच पर तेल गरम करें और उसे घुमाकर तली पर फैला दें। 2 कप कटी हुई सब्ज़ियाँ, प्याज़ और सीज़निंग मिश्रण को 8 से 10 मिनट तक, बीच-बीच में चलाते हुए, तब तक पकाएँ जब तक वे नरम पर हल्के कुरकुरे न रहें। (अगर सब्ज़ियाँ सूखने लगें या जलने लगें, तो सॉसपैन में थोड़ा पानी डाल दें।)","ब्रॉथ डालकर मिलाएँ। आँच को मध्यम तेज़ करें और उबाल आने दें। आँच कम करें और 15 मिनट तक, बीच-बीच में चलाते हुए, धीमी आँच पर पकाएँ ताकि स्वाद आपस में मिल जाएँ। पालक डालकर मिलाएँ। हर कटोरी पर पारमेज़न चीज़ छिड़कें।","सुझाव: गाजर जैसी सख़्त सब्ज़ियों को तोरी जैसी नरम सब्ज़ियों से छोटे टुकड़ों में काटें, ताकि सारी सब्ज़ियाँ लगभग एक ही गति से पकें। अगर आप इस व्यंजन को शाकाहारी बनाना चाहते हैं, तो चिकन ब्रॉथ की जगह वेजिटेबल ब्रॉथ ज़रूर इस्तेमाल करें।"]))
r.append(R(6525164,"साबुत गेहूँ की ताज़ा जिंजरब्रेड",
"यह ताज़ा जिंजरब्रेड लोफ़ एक पसंदीदा क्लासिक का सेहतमंद रूप है। इसमें अदरक और गुड़ का गरम, मसालेदार स्वाद है, साथ ही साबुत गेहूँ के आटे के गुण भी हैं। यह आपके त्योहारी दावत में एक शानदार जोड़ है जिसका आनंद पूरा परिवार ज़रूर लेगा! यह मधुमेह के अनुकूल व्यंजन त्योहारी कुकी स्वैप में ले जाने या त्योहारी भोजन में परोसकर मौसम का जश्न मनाने के लिए एक बढ़िया विकल्प है।",
"12","1 स्लाइस",
["2 कप साबुत गेहूँ का आटा","1/3 कप ब्राउन शुगर विकल्प","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच नमक","1 छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच पिसी अदरक","1/2 छोटा चम्मच पिसा जायफल","1/4 छोटा चम्मच पिसी लौंग","1/2 कप बिना चीनी की सेब की प्यूरी (एप्पलसॉस)","1/3 कप मेपल सिरप","1/4 कप वनस्पति तेल","2 बड़े चम्मच ताज़ा अदरक (कसा हुआ)","2 बड़े अंडे","1 छोटा चम्मच वेनिला एक्सट्रैक्ट","1 कप पानी (गरम)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। 9x5 इंच के लोफ़ पैन में चिकनाई लगाएँ।","एक बड़े कटोरे में साबुत गेहूँ का आटा, ब्राउन शुगर विकल्प, बेकिंग सोडा, बेकिंग पाउडर, नमक, दालचीनी, अदरक, जायफल और लौंग को फेंटकर मिलाएँ।","दूसरे कटोरे में एप्पलसॉस, मेपल सिरप, वनस्पति तेल, ताज़ा कसा हुआ अदरक, अंडे और वेनिला एक्सट्रैक्ट को मिलाएँ। अच्छी तरह मिलने तक मिलाएँ।","गीली सामग्री को धीरे-धीरे सूखी सामग्री में डालें और बस मिलने तक चलाएँ। ज़्यादा न मिलाएँ।","घोल को हल्के से चलाते हुए उसमें धीरे-धीरे गरम पानी डालें। घोल पतला होगा।","घोल को तैयार लोफ़ पैन में डालें।","पहले से गरम ओवन में लगभग 45–50 मिनट तक बेक करें, या जब तक ब्रेड के बीच में टूथपिक डालने पर वह साफ़ न निकले।","बेक होने के बाद जिंजरब्रेड को ओवन से निकालें और पैन में लगभग 10 मिनट ठंडा होने दें। फिर उसे सावधानी से पैन से निकालें और पूरी तरह ठंडा होने के लिए वायर रैक पर रखें।"]))
r.append(R(6525410,"ठंडा खीरे का सूप और ग्रिल्ड झींगा ओपन-फ़ेस सैंडविच",
"खीरे जैसा ठंडा और ताज़गी भरा यह सूप ग्रिल्ड झींगे और तीखे एवोकाडो आयोली वाले ओपन-फ़ेस सैंडविच के साथ बिल्कुल सही बैठता है। अगर तीखापन ज़्यादा लगे, तो आप हॉट सॉस छोड़ सकते हैं या बस एक बूँद डाल सकते हैं।",
"4","1 ¼ कप सूप + 1 ओपन-फ़ेस सैंडविच",
["2 मध्यम खीरे (तीन टुकड़ों में और फिर लंबाई में आधे कटे हुए)","2 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","4 बड़े चम्मच नीबू का रस (2 मध्यम नीबू से, बाँटा हुआ)","1 बड़ा चम्मच नीबू का छिलका (कसा हुआ)","1 बड़ा चम्मच ताज़ा सोआ","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","8 औंस झींगे (छिले और नस निकाले हुए)","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/4 छोटा चम्मच काली मिर्च","4 बड़े चम्मच लाइट मेयोनेज़","1/2 मध्यम एवोकाडो","1/8 छोटा चम्मच हॉट सॉस","1 कप अरुगुला","4 स्लाइस साबुत अनाज की ब्रेड (टोस्ट की हुई)"],
["सूप बनाने के लिए आधे खीरे को चॉपिंग ब्लेड लगे फ़ूड प्रोसेसर में डालें। इन्हें छोटे टुकड़ों में कटने तक चलाएँ। बाक़ी खीरे के टुकड़े डालें और उन्हें भी छोटे टुकड़ों में कटने तक चलाएँ।","योगर्ट, नीबू का रस, नीबू का छिलका और सोआ डालें और तब तक चलाएँ जब तक सब तरल न हो जाए और खीरे के सारे टुकड़े प्यूरी न बन जाएँ।","ग्रिल पैन या आउटडोर ग्रिल पर कुकिंग स्प्रे करें और उसे मध्यम तक गरम करें। झींगों को जैतून के तेल और काली मिर्च के साथ मिलाएँ। उन्हें पहले से गरम ग्रिल पर रखें और 1 मिनट पकाएँ। झींगों को पलटें और 1 मिनट और पकाएँ। झींगे जल्दी पक जाते हैं, इसलिए ध्यान रखें कि वे ज़्यादा न पकें। उन्हें ग्रिल से निकालकर प्लेट में रखें।","एक छोटे कटोरे में एवोकाडो को मसलें और उसमें मेयोनेज़, नीबू का रस और हॉट सॉस डालें, और तब तक मिलाएँ जब तक रंग हल्का हरा न हो जाए और एवोकाडो अच्छी तरह मिलकर चिकना न हो जाए।","हर टोस्ट स्लाइस पर 1 बड़ा चम्मच एवोकाडो आयोली फैलाएँ। उस पर 1/4 कप अरुगुला और 3 झींगे रखें। साथ में किनारे पर 1 ¼ कप सूप परोसें।"]))
r.append(R(6526217,"शीट पैन टोफ़ू फ़ाजिटा",
"शीट पैन डिनर बहुत ज़्यादा सफ़ाई के बिना पौष्टिक भोजन का आनंद लेने का एक तेज़ और आसान तरीका है। मधुमेह के अनुकूल यह टोफ़ू फ़ाजिटा भोजन ऐसा है जो पूरे परिवार को पसंद आएगा, और इसमें पौधों से मिलने वाला प्रोटीन है जो आपको देर तक भरा हुआ और संतुष्ट रखता है।",
"4","1 टॉर्टिला + भरावन का 1/4 भाग",
["16 औंस एक्स्ट्रा फ़र्म टोफ़ू (दबाकर पानी निकाला हुआ और टुकड़ों में कटा हुआ)","1 मध्यम लाल शिमला मिर्च (स्लाइस की हुई)","1 मध्यम पीली शिमला मिर्च (स्लाइस की हुई)","1 मध्यम लाल प्याज़ (पतले स्लाइस में कटा हुआ)","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच कम सोडियम वाला टैको सीज़निंग","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच स्मोक्ड पैपरिका","1/2 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच काली मिर्च","4 साबुत कम कार्ब वाले साबुत गेहूँ के बुरिटो रैप","2 बड़े चम्मच ताज़ा धनिया पत्ती (कटी हुई)","1 साबुत नीबू (फाँकों में कटा हुआ)"],
["अपने ओवन को 400 डिग्री F पर पहले से गरम करें। शीट पैन पर बेकिंग पेपर बिछाएँ।","टोफ़ू को दबाकर अतिरिक्त पानी निकालें, फिर उसे टुकड़ों में काटें।","एक बड़े कटोरे में टोफ़ू के टुकड़े, स्लाइस की हुई शिमला मिर्च और स्लाइस किया हुआ लाल प्याज़ मिलाएँ।","एक छोटे कटोरे में जैतून का तेल, टैको सीज़निंग, पिसा जीरा, स्मोक्ड पैपरिका, चिली पाउडर और काली मिर्च को फेंटकर मैरिनेड तैयार करें।","मैरिनेड को टोफ़ू और सब्ज़ियों पर डालें। सब कुछ बराबर लगने तक मिलाएँ। इसे कम से कम 30 मिनट मैरिनेट होने दें।","मैरिनेट किए हुए टोफ़ू और सब्ज़ियों को शीट पर बराबर फैलाएँ।","पहले से गरम ओवन में 25 मिनट तक भूनें, या जब तक टोफ़ू सुनहरा और सब्ज़ियाँ नरम न हो जाएँ, बीच में एक बार चलाएँ।","फ़ाजिटा का भरावन रैप में बराबर बाँटें।","शीट पैन टोफ़ू फ़ाजिटा परोसें और कटे हुए धनिये और नीबू की फाँकों से सजाएँ।"]))
r.append(R(6526998,"सैलड बार गज़पाचो सलाद",
"यह स्वादिष्ट सलाद टमाटर पर आधारित हल्की ड्रेसिंग का उपयोग करता है और हरी पत्तेदार सब्ज़ियों तथा अन्य पोषक तत्वों से भरपूर सब्ज़ियों से भरा है। तैयारी का समय बचाने के लिए इनमें से जितनी हो सके उतनी सब्ज़ियाँ अपने किराने की दुकान के सैलड बार से पहले से कटी हुई ख़रीदें।",
"5","2 कप",
["2 कप छोले, लाल राजमा या काली बीन्स (सैलड बार से या डिब्बाबंद, पानी निथारे और धुले हुए)","1 1/2 कप टमाटर (टुकड़ों में कटे हुए)","2/3 कप मक्का (कॉर्न)","2/3 कप खीरा (टुकड़ों में कटा हुआ)","3 बड़े चम्मच लाल प्याज़ (टुकड़ों में कटा हुआ)","2 बड़े चम्मच धनिया पत्ती (बारीक कटी हुई)","1/4 कप टमाटर का रस (कम सोडियम वाला)","2 बड़े चम्मच ताज़ा नीबू का रस","1 बड़ा चम्मच जैतून का तेल","1/2 छोटा चम्मच चिली पाउडर (माइल्ड या हॉट)","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च","5 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ"],
["बीन्स, टमाटर, मक्का, खीरा, लाल प्याज़ और धनिया पत्ती को मिलाएँ।","एक छोटे कटोरे में टमाटर का रस, नीबू का रस, जैतून का तेल, चिली पाउडर, नमक और काली मिर्च को फेंटकर मिलाएँ। इसे सलाद पर डालें और धीरे से मिलाएँ। मिली-जुली हरी पत्तेदार सब्ज़ियों के ऊपर परोसें।"]))
r.append(R(6527440,"शकरकंद का सलाद",
"किसने कहा कि आलू का सलाद सिर्फ़ सफ़ेद आलू से बन सकता है? यह व्यंजन आपके अगले गर्मियों के पिकनिक में एक सुखद आश्चर्य होगा।",
"12","1/2 कप",
["3 बड़े शकरकंद (लगभग 13 औंस प्रत्येक)","4 स्लाइस टर्की बेकन","2 बड़े चम्मच जैतून का तेल","1 बड़ा चम्मच सेब का सिरका","1/8 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच लहसुन पाउडर","3 डंठल अजवाइन (सेलरी) (टुकड़ों में कटे हुए)","2 डंठल हरा प्याज़ (स्कैलियन) (स्लाइस किए हुए)"],
["शकरकंद छीलें और उन्हें चौकोर टुकड़ों में काटें। शकरकंद को एक बड़े बर्तन में रखें। पानी डालकर ढकें और उबाल आने दें। नरम होने तक लगभग 5-7 मिनट उबालें। आलू का पानी निथारें और ठंडे पानी से धोएँ; ठंडा होने दें।","जब तक आलू पक रहे हों, बेकन को कुरकुरा होने तक पकाएँ, फिर उसे छोटे टुकड़ों में काटें या चूरा करें।","एक छोटे कटोरे में जैतून का तेल, सेब का सिरका, काली मिर्च और लहसुन पाउडर को फेंटकर मिलाएँ।","शकरकंद को परोसने वाले कटोरे में रखें और उसमें अजवाइन, हरा प्याज़ और टर्की बेकन डालें। ड्रेसिंग को सलाद पर डालें और तब तक मिलाएँ जब तक शकरकंद पर ड्रेसिंग न लग जाए। ठंडा परोसें।"]))
r.append(R(6527594,"चिकन के साथ आम-आम सलाद",
"पारंपरिक चिकन सलाद में आम मिलाने से वह थोड़ा और जानदार बन जाता है! यह रेसिपी और भी बहुत कुछ आपको द न्यू सोल फ़ूड कुकबुक फ़ॉर पीपल विद डायबिटीज़ में मिलेगा।",
"6","1 कप चिकन सलाद + 3 लेट्यूस पत्ते",
["1/3 कप लाइट मेयोनेज़","3 डंठल हरा प्याज़ (स्कैलियन) (कटे हुए)","2 कप पका हुआ चिकन ब्रेस्ट (टुकड़ों में कटा हुआ)","2 कप आम (कटा हुआ)","1 मध्यम हरी शिमला मिर्च (बीज निकाली हुई और कटी हुई)","1 बड़ा चम्मच सेब का सिरका","2 बड़े चम्मच नीबू का रस","1 छोटा चम्मच चीनी","18 पत्ते रोमेन लेट्यूस"],
["मेयोनेज़ और हरे प्याज़ को एक छोटे कटोरे में मिलाएँ, ढकें और ठंडा करें। चिकन, आम और शिमला मिर्च को एक बड़े कटोरे में मिलाएँ।","सिरका, नीबू का रस और चीनी को कसकर बंद होने वाले ढक्कन वाले डिब्बे में मिलाएँ। अच्छी तरह हिलाएँ। नीबू के मिश्रण को मेयोनेज़ और हरे प्याज़ के मिश्रण में डालकर अच्छी तरह मिलाएँ।","ड्रेसिंग को चिकन और आम पर डालें, अच्छी तरह मिलाएँ और 30 मिनट ठंडा करें। परोसने के लिए, इसे लेट्यूस के पत्तों से सजी प्लेट पर चम्मच से रखें।"]))
r.append(R(6529405,"क्रिस्पी आलू टैको बाउल",
"इस टैको बाउल में भुने हुए सफ़ेद आलू और मुलायम फूलगोभी के चावल का भरपूर आधार है, जिसके ऊपर स्वादिष्ट कीमा बीफ़, मशरूम और लाल शिमला मिर्च डाली जाती है। ताज़ा नीबू का रस और धनिया पत्ती हर निवाले को ताज़गी देते हैं, जबकि मलाईदार एवोकाडो भरपूरता और संतुलन जोड़ता है। यह क्लासिक टैको स्वादों का एक संतोषजनक, सब्ज़ियों से भरा, उच्च फ़ाइबर वाला रूप है जो हफ़्ते के दिनों के लिए काफ़ी आसान है और अपनी पसंद से बाउल बनाने के लिए एकदम सही है।",
"4","1 बाउल (लगभग 2 1/2 कप)",
["12 औंस सफ़ेद आलू (लगभग 2 मध्यम, 1/2 इंच के टुकड़ों में कटे हुए)","1 बड़ा चम्मच जैतून का तेल (बाँटा हुआ)","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","8 औंस 4% चर्बी वाला एक्स्ट्रा लीन कीमा बीफ़","8 औंस मशरूम (बारीक कटे हुए)","1 कप लाल शिमला मिर्च (लगभग 1 मध्यम शिमला मिर्च, टुकड़ों में कटी हुई)","1 छोटा चम्मच चिली पाउडर","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच स्मोक्ड पैपरिका","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच प्याज़ पाउडर","1/2 कप बिना नमक मिलाया टमाटर सॉस","1/4 कप पानी","2 कप फूलगोभी के चावल","2 बड़े चम्मच ताज़ा नीबू का रस (लगभग 1 नीबू से)","1/4 कप ताज़ा धनिया पत्ती (कटी हुई)","8 साबुत चेरी टमाटर (आधे कटे हुए)","1 मध्यम एवोकाडो (स्लाइस किया हुआ)"],
["ओवन को 425 डिग्री F पर पहले से गरम करें। कटे हुए आलू को 1 1/2 छोटा चम्मच जैतून का तेल, 1/4 छोटा चम्मच नमक और 1/8 छोटा चम्मच काली मिर्च के साथ मिलाएँ। इन्हें बेकिंग शीट पर एक परत में फैलाएँ और 20–25 मिनट तक भूनें, बीच में एक बार चलाएँ, जब तक वे नरम और हल्के भूरे न हो जाएँ।","उसी कड़ाही में बाक़ी 1 1/2 छोटा चम्मच जैतून का तेल मध्यम आँच पर गरम करें। कीमा बीफ़, कटे हुए मशरूम और कटी हुई लाल शिमला मिर्च डालें। बीफ़ को तोड़ते हुए 8–10 मिनट पकाएँ, जब तक मांस पूरी तरह पक न जाए और सब्ज़ियाँ नरम न हो जाएँ।","चिली पाउडर, जीरा, स्मोक्ड पैपरिका, लहसुन पाउडर, प्याज़ पाउडर, बचा हुआ 1/4 छोटा चम्मच नमक और 1/4 छोटा चम्मच काली मिर्च मिलाएँ। खुशबू आने तक 1–2 मिनट पकाएँ। टमाटर सॉस और पानी डालें और धीमी आँच पर उबलने दें। उबाल आने तक पकाएँ, फिर आँच कम करें और 5-7 मिनट तक धीमी आँच पर पकाएँ, जब तक तरल कम न हो जाए। आँच से उतार लें।","जब तक बीफ़ का मिश्रण धीमी आँच पर पक रहा हो, एक बड़ी नॉनस्टिक कड़ाही में मध्यम आँच पर फूलगोभी के चावल को 3–4 मिनट तक, बीच-बीच में चलाते हुए, अंदर तक गरम होने तक गरम करें। धनिया पत्ती और नीबू का रस डालकर मिलाएँ। परोसने तक गरम रखें।","फूलगोभी के चावल को चार बाउल में बराबर बाँटें। हर बाउल के ऊपर भुने हुए आलू, बीफ़-मशरूम-शिमला मिर्च का मिश्रण, दो टमाटर और स्लाइस किए हुए एवोकाडो का 1/4 भाग बराबर रखें।"]))
r.append(R(6530550,"बच्चों के लिए इंद्रधनुषी फलों की प्लैटर",
"एक तेज़, आसान और रंगीन रेसिपी जो कोई भी बना सकता है! इसे नाश्ते, स्नैक या मिठाई के रूप में भी आज़माएँ।",
"25",None,
["8 औंस वेनिला ग्रीक योगर्ट (100 कैलोरी)","1 बड़ा चम्मच चिया बीज","1/8 छोटा चम्मच पिसी दालचीनी","4 कप साबुत स्ट्रॉबेरी (डंठल हटाई हुई)","4 कप खरबूजा (कैंटालूप) (चौकोर टुकड़ों में कटा हुआ)","1 ताज़ा अनानास (छिला हुआ, बीच का हिस्सा निकाला हुआ और चौकोर टुकड़ों में कटा हुआ (लगभग 4 कप))","3 कप हरे अंगूर","4 कप ब्लूबेरी","3 कप लाल अंगूर","3 कप ब्लैकबेरी"],
["योगर्ट और चिया बीज को मिलाएँ। रात भर रेफ़्रिजरेटर में रखें। उसमें 1/8 छोटा चम्मच दालचीनी मिलाएँ।","एक बहुत बड़ी प्लैटर पर इंद्रधनुष की आकृति का ऊपरी हिस्सा बनाने के लिए स्ट्रॉबेरी को सबसे ऊपरी पंक्ति में रखें।","खरबूजे के टुकड़ों को स्ट्रॉबेरी के नीचे दूसरी पंक्ति के रूप में रखें। इसी तरह अनानास से शुरू करके ब्लैकबेरी तक आगे बढ़ते हुए इंद्रधनुष की आकृति पूरी करें।"]))
